package com.example.bible.data

data class DictionaryEntry(
    val word: String,
    val definition: String,
    val seeAlso: List<String> = emptyList(),
)

object BibleDictionary {

    private val entries: Map<String, DictionaryEntry> by lazy {
        buildMap {
            fun add(word: String, definition: String, seeAlso: List<String> = emptyList()) {
                put(word.lowercase(), DictionaryEntry(word, definition, seeAlso))
            }

            add("Бог", "Верховное Существо, Творец неба и земли. В еврейском тексте — Элохим (אֱלֹהִים), Яхве (יהוה). Единый в трёх Лицах: Отец, Сын и Святой Дух.", listOf("Господь", "Творец", "Всевышний"))
            add("Господь", "Титул Бога, указывающий на Его владычество. В еврейском — Адонай (אֲדֹנָי), часто замена непроизносимого имени YHWH.", listOf("Бог", "Яхве"))
            add("Яхве", "Собственное имя Бога в Ветхом Завете (тетраграмматон יהוה). Означает «Сущий», «Я есмь Тот, Кто Я есмь» (Исх 3:14).", listOf("Бог", "Господь", "Иегова"))
            add("Иегова", "Произношение имени Бога (YHWH), возникшее от соединения согласных YHWH с гласными слова Адонай. Более точное произношение — Яхве.", listOf("Яхве", "Бог"))
            add("Христос", "Греческий перевод (Χριστός) еврейского слова «Мессия» (Машиах), означающего «Помазанник». Титул Иисуса как обещанного Спасителя.", listOf("Мессия", "Иисус", "Помазанник"))
            add("Мессия", "Еврейское «Машиах» (מָשִׁיחַ) — «Помазанник». Обещанный Богом Царь и Спаситель Израиля. Христиане верят, что это Иисус из Назарета.", listOf("Христос", "Помазанник"))
            add("Иисус", "Греческая форма еврейского имени Иешуа (יֵשׁוּעַ), означающего «Господь спасает». Иисус Христос — центральная личность Нового Завета.", listOf("Христос", "Мессия", "Спаситель"))
            add("Дух", "Может означать: 1) Святой Дух — третье Лицо Троицы; 2) дух человека — нематериальная часть человека; 3) злой дух — падший ангел.", listOf("Святой", "Троица"))
            add("Святой", "Отделённый, посвящённый Богу. Применяется к Богу (абсолютная святость), к верующим (посвящённые Богу), к предметам и местам.", listOf("Освящение"))
            add("Ангел", "Греч. ἄγγελος — «вестник». Духовные существа, служители Бога. В Библии выполняют роль Божьих посланников и защитников верующих.", listOf("Архангел", "Серафим", "Херувим"))
            add("Архангел", "Главный ангел. В Библии по имени упоминается Михаил (Иуды 1:9). Гавриил также занимает высокое положение среди ангелов.", listOf("Ангел", "Михаил", "Гавриил"))
            add("Грех", "Еврейское хатта (חַטָּא) — «промах, отклонение от цели». Нарушение Божьего закона, противление воле Бога. Причина разделения человека с Богом.", listOf("Покаяние", "Искупление", "Прощение"))
            add("Покаяние", "Греч. μετάνοια — «перемена ума». Глубокое осознание своих грехов, сожаление о них и решимость изменить жизнь, обращение к Богу.", listOf("Грех", "Прощение", "Обращение"))
            add("Вера", "Греч. πίστις — доверие Богу и Его обещаниям, убеждённость в невидимом (Евр 11:1). Основа отношений человека с Богом.", listOf("Надежда", "Любовь", "Спасение"))
            add("Благодать", "Греч. χάρις — незаслуженная Божья милость и благоволение. Дар спасения, который нельзя заработать делами (Еф 2:8-9).", listOf("Милость", "Спасение", "Дар"))
            add("Спасение", "Избавление от греха и его последствий через веру в Иисуса Христа. Включает оправдание, освящение и прославление.", listOf("Искупление", "Оправдание", "Благодать"))
            add("Искупление", "Выкуп, освобождение ценой жертвы. Христос искупил людей Своей кровью на кресте (1 Пет 1:18-19).", listOf("Спасение", "Жертва", "Кровь"))
            add("Оправдание", "Юридический термин — объявление грешника праведным перед Богом на основании веры во Христа (Рим 3:24, 5:1).", listOf("Спасение", "Праведность", "Вера"))
            add("Праведность", "Соответствие Божьему стандарту. Праведность Божья — Его безупречная справедливость. Праведность верующего — вменённая через веру.", listOf("Оправдание", "Святость"))
            add("Крещение", "Греч. βάπτισμα — «погружение». Обряд посвящения в христианскую веру через погружение в воду или обливание. Символ смерти и воскресения со Христом.", listOf("Вода", "Обращение"))
            add("Церковь", "Греч. ἐκκλησία — «собрание призванных». Община верующих во Христа. Может означать поместную общину или вселенскую Церковь.", listOf("Собрание", "Тело"))
            add("Евангелие", "Греч. εὐαγγέλιον — «благая весть». Весть о спасении через Иисуса Христа. Также название четырёх книг НЗ (Матфей, Марк, Лука, Иоанн).", listOf("Благовестие", "Спасение"))
            add("Апостол", "Греч. ἀπόστολος — «посланник». Двенадцать учеников Иисуса, а также Павел и другие, особо посланные для проповеди Евангелия.", listOf("Ученик", "Посланник"))
            add("Пророк", "Человек, говорящий от имени Бога. Пророки Ветхого Завета возвещали волю Бога и предсказывали будущее, в т.ч. пришествие Мессии.", listOf("Пророчество", "Видение"))
            add("Завет", "Еврейское берит (בְּרִית) — «договор, союз». Соглашение между Богом и людьми. Ветхий Завет (через Моисея) и Новый Завет (через Христа).", listOf("Договор", "Обещание"))
            add("Закон", "Тора (תּוֹרָה) — учение, наставление. Первые пять книг Моисея (Пятикнижие). Также — вся система Божьих заповедей и установлений.", listOf("Тора", "Заповедь", "Моисей"))
            add("Тора", "Еврейское «учение, наставление». Пять книг Моисея: Бытие, Исход, Левит, Числа, Второзаконие. Основа иудейского и христианского вероучения.", listOf("Закон", "Пятикнижие"))
            add("Заповедь", "Божье повеление. Десять заповедей даны через Моисея на горе Синай (Исх 20). Христос обобщил их в двух: любовь к Богу и ближнему.", listOf("Закон", "Синай"))
            add("Жертва", "Приношение Богу как выражение поклонения, благодарности или искупления. Ветхозаветные жертвы прообразовали жертву Христа.", listOf("Искупление", "Кровь", "Алтарь"))
            add("Кровь", "Символ жизни (Лев 17:11). Кровь жертвенных животных — средство очищения в ВЗ. Кровь Христа — основание нового завета и прощения грехов.", listOf("Жертва", "Искупление"))
            add("Воскресение", "Восстание из мёртвых. Воскресение Иисуса Христа на третий день — центральное событие христианской веры. Верующим обещано будущее воскресение.", listOf("Смерть", "Жизнь"))
            add("Рай", "Место блаженства праведных. В НЗ — место пребывания с Богом после смерти (Лк 23:43). Также Эдемский сад — первоначальное жилище человека.", listOf("Небо", "Эдем"))
            add("Ад", "Место наказания нечестивых. Еврейское «шеол» — обитель мёртвых. Греческое «геенна» (γέεννα) — место вечного наказания.", listOf("Шеол", "Геенна", "Суд"))
            add("Царство", "Царство Божие/Небесное — владычество Бога. Присутствует духовно уже сейчас в сердцах верующих и наступит полностью при втором пришествии Христа.", listOf("Царь", "Небо"))
            add("Молитва", "Общение с Богом. Включает прославление, благодарение, исповедание грехов и просьбы. Иисус научил учеников молитве «Отче наш» (Мф 6:9-13).", listOf("Поклонение", "Прошение"))
            add("Любовь", "Греч. ἀγάπη — высшая, жертвенная любовь. Основное свойство Бога (1 Ин 4:8). Главная заповедь христианина (1 Кор 13).", listOf("Агапе", "Милость"))
            add("Надежда", "Уверенное ожидание исполнения Божьих обещаний. Христианская надежда основана на воскресении Христа и обещании вечной жизни.", listOf("Вера", "Обещание"))
            add("Пасха", "Еврейский праздник (פֶּסַח — Песах) в память исхода из Египта. В христианстве — праздник воскресения Иисуса Христа.", listOf("Исход", "Агнец"))
            add("Агнец", "Ягнёнок, используемый как жертвенное животное. «Агнец Божий» — титул Иисуса Христа (Ин 1:29), указывающий на Его искупительную жертву.", listOf("Жертва", "Христос", "Пасха"))
            add("Крест", "Орудие казни, на котором был распят Иисус. Для христиан — символ спасения, жертвенной любви Бога и победы над смертью.", listOf("Распятие", "Жертва", "Спасение"))
            add("Небо", "1) Физическое небо — атмосфера и космос. 2) Обитель Бога и ангелов. 3) Будущее место вечного пребывания праведных.", listOf("Рай", "Царство"))
            add("Земля", "1) Физический мир, сотворённый Богом. 2) Обетованная земля (Ханаан) — земля, обещанная Богом Аврааму и его потомкам.", listOf("Творение", "Ханаан"))
            add("Душа", "Еврейское нефеш (נֶפֶשׁ) — жизненное начало, личность человека. Нематериальная часть человека, способная к общению с Богом.", listOf("Дух", "Тело"))
            add("Истина", "Греч. ἀλήθεια — то, что соответствует действительности и Божьей воле. Иисус сказал: «Я есмь путь и истина и жизнь» (Ин 14:6).", listOf("Правда", "Слово"))
            add("Слово", "Греч. λόγος — в Ин 1:1 титул Иисуса Христа («В начале было Слово»). Также — Библия как Слово Божье, откровение Его воли.", listOf("Логос", "Библия", "Писание"))
            add("Мир", "1) Греч. εἰρήνη — отсутствие вражды, гармония с Богом и людьми. 2) Греч. κόσμος — мир, вселенная, человечество.", listOf("Покой", "Шалом"))
            add("Сион", "Холм в Иерусалиме, ставший символом Божьего присутствия. Поэтически — Иерусалим, Израиль или небесный город Бога.", listOf("Иерусалим", "Храм"))
            add("Иерусалим", "Святой город, столица Израиля. Место храма Божьего. В Откровении — символ небесного города, «Нового Иерусалима» (Откр 21:2).", listOf("Сион", "Храм"))
            add("Храм", "Дом Божий в Иерусалиме. Первый построен Соломоном, второй — после вавилонского плена. В НЗ тело верующего — храм Святого Духа (1 Кор 6:19).", listOf("Скиния", "Иерусалим"))
            add("Скиния", "Переносной шатёр поклонения, построенный по указанию Бога в пустыне (Исх 25-27). Предшественница Иерусалимского храма.", listOf("Храм", "Ковчег"))
            add("Ковчег", "1) Ковчег Завета — золотой ящик с Десятью заповедями в скинии/храме. 2) Ноев ковчег — корабль спасения от потопа.", listOf("Скиния", "Ной"))
            add("Суд", "Божье решение о праведности или виновности. Последний суд (Откр 20:11-15) — окончательное определение вечной судьбы каждого человека.", listOf("Справедливость", "Наказание"))
            add("Притча", "Краткий рассказ с духовным смыслом. Иисус часто учил притчами (о сеятеле, блудном сыне, добром самарянине и др.).", listOf("Учение", "Иносказание"))
            add("Аминь", "Еврейское «да будет так», «истинно». Слово подтверждения, завершающее молитвы и благословения. Иисус использовал «аминь, аминь» для усиления.", listOf("Молитва", "Истина"))
            add("Аллилуйя", "Еврейское «хвалите Яхве» (הַלְלוּ יָהּ). Восклицание хвалы Богу, часто встречающееся в Псалмах и в Откровении (19:1-6).", listOf("Хвала", "Поклонение"))
            add("Осанна", "Еврейское «спаси же!» Восклицание народа при входе Иисуса в Иерусалим (Мф 21:9). Стало выражением хвалы и радости.", listOf("Хвала", "Иерусалим"))
            add("Сатана", "Еврейское «противник». Падший ангел, враг Бога и людей. Также называется дьяволом, лукавым, змеем, князем мира сего.", listOf("Дьявол", "Искушение"))
            add("Благословение", "Призвание Божьей милости и защиты на человека. Также — Божий дар, благо. Бог благословил Авраама, чтобы он стал благословением для всех народов.", listOf("Милость", "Дар"))

            add("Авраам", "Праотец еврейского народа. Бог заключил с ним завет и обещал многочисленное потомство и Обетованную землю (Быт 12-25). Пример веры (Евр 11:8-12).", listOf("Завет", "Вера", "Исаак"))
            add("Моисей", "Пророк и вождь, выведший Израиль из Египта. Получил от Бога Десять заповедей на горе Синай. Автор Пятикнижия (Торы).", listOf("Закон", "Тора", "Исход"))
            add("Давид", "Второй царь Израиля, «муж по сердцу Божьему» (1 Цар 13:14). Автор многих псалмов. Предок Иисуса Христа по плоти.", listOf("Царь", "Псалом"))
            add("Соломон", "Сын Давида, третий царь Израиля. Известен мудростью. Построил Первый Иерусалимский храм. Автор Притчей, Екклесиаста и Песни Песней.", listOf("Храм", "Давид", "Мудрость"))
            add("Илия", "Великий пророк Ветхого Завета, обличавший идолопоклонство. Был вознесён на небо живым на огненной колеснице (4 Цар 2:11).", listOf("Пророк"))
            add("Исаия", "Ветхозаветный пророк (VIII в. до н.э.). Его книга содержит пророчества о Мессии, включая знаменитую 53-ю главу о Страдающем Рабе.", listOf("Пророк", "Мессия"))
            add("Пётр", "Симон Пётр — один из двенадцати апостолов, лидер ранней Церкви. Иисус назвал его «камнем» (Мф 16:18). Автор двух посланий НЗ.", listOf("Апостол", "Церковь"))
            add("Павел", "Апостол язычников. До обращения — фарисей Савл, гонитель христиан. Автор 13 посланий Нового Завета. Основал множество церквей.", listOf("Апостол", "Евангелие"))
            add("Иоанн", "1) Апостол, «ученик, которого любил Иисус». Автор Евангелия, трёх посланий и Откровения. 2) Иоанн Креститель — предтеча Христа.", listOf("Апостол", "Крещение"))
            add("Адам", "Первый человек, сотворённый Богом из праха земного (Быт 2:7). Через его непослушание грех вошёл в мир (Рим 5:12).", listOf("Грех", "Ева", "Творение"))
            add("Ной", "Праведник, спасённый от потопа в ковчеге. Бог заключил с ним завет и дал знамение радуги (Быт 6-9).", listOf("Ковчег", "Завет", "Потоп"))
            add("Иаков", "1) Сын Исаака, позже названный Израиль. Отец двенадцати колен. 2) Брат Господень, автор послания, глава Иерусалимской церкви.", listOf("Израиль", "Авраам"))
            add("Израиль", "1) Имя, данное Богом Иакову (Быт 32:28). 2) Народ — потомки двенадцати сыновей Иакова. 3) Земля обетованная. 4) Северное царство.", listOf("Иаков", "Завет"))

            add("Фарисей", "Член иудейской религиозной партии, строго соблюдавшей Закон и устное предание. Иисус часто обличал их лицемерие (Мф 23).", listOf("Закон", "Книжник"))
            add("Левит", "Потомок Левия, одного из 12 сыновей Иакова. Левиты служили при скинии/храме. Священники были из семьи Аарона.", listOf("Священник", "Храм"))
            add("Священник", "Посредник между Богом и людьми, совершающий жертвоприношения. Ветхозаветные священники — из рода Аарона. Христос — вечный Первосвященник (Евр 7).", listOf("Левит", "Жертва", "Храм"))
            add("Псалом", "Священная песнь или молитва. Книга Псалмов (Псалтирь) содержит 150 псалмов. Многие написаны царём Давидом.", listOf("Давид", "Молитва", "Хвала"))
            add("Откровение", "1) Самораскрытие Бога людям. 2) Последняя книга Библии (Апокалипсис), написанная апостолом Иоанном о будущих событиях и конце времён.", listOf("Пророчество", "Иоанн"))
            add("Троица", "Христианское учение о том, что единый Бог существует в трёх Лицах: Отец, Сын (Иисус Христос) и Святой Дух — равных в божественности.", listOf("Бог", "Христос", "Дух"))
            add("Обетование", "Божье обещание, данное Его народу. Ключевые обетования: потомство и земля Аврааму, вечное царство Давиду, новый завет через Христа.", listOf("Завет", "Авраам", "Надежда"))
            add("Мудрость", "В Библии — практическое умение жить по Божьей воле. Книги мудрости: Притчи, Екклесиаст, Иов. «Начало мудрости — страх Господень» (Прит 9:10).", listOf("Закон", "Соломон"))
            add("Благовестие", "Проповедь Евангелия, распространение благой вести о спасении через Иисуса Христа. Великое поручение (Мф 28:19-20).", listOf("Евангелие", "Апостол"))
            add("Освящение", "Процесс отделения от греха и уподобления Христу через действие Святого Духа. Происходит на протяжении всей жизни верующего.", listOf("Святой", "Дух", "Спасение"))
            add("Помазанник", "Тот, на кого возлит елей в знак особого Божьего избрания. Помазывали царей, священников, пророков. Христос — Помазанник Божий.", listOf("Христос", "Мессия"))
