    }

    fun lookup(word: String): DictionaryEntry? {
        val normalized = word.trim().lowercase()
            .removeSuffix(".")
            .removeSuffix(",")
            .removeSuffix(";")
            .removeSuffix(":")
            .removeSuffix("!")
            .removeSuffix("?")
            .removeSuffix("»")
            .removePrefix("«")
        return entries[normalized] ?: findByPrefix(normalized)
    }

    fun lookupOrCreate(word: String): DictionaryEntry {
        val found = lookup(word)
        if (found != null) return found
        val clean = word.trim()
            .removeSuffix(".").removeSuffix(",").removeSuffix(";")
            .removeSuffix(":").removeSuffix("!").removeSuffix("?")
            .removeSuffix("»").removePrefix("«")
        return DictionaryEntry(
            word = clean,
            definition = "Слово «$clean» встречается в тексте Библии. Для подробного толкования используйте подстрочный перевод (Винокуров) со справочником Стронга.",
        )
    }

    private fun findByPrefix(word: String): DictionaryEntry? {
        if (word.length < 3) return null
        return entries.values.firstOrNull { entry ->
            entry.word.lowercase().startsWith(word) ||
                    word.startsWith(entry.word.lowercase())
        }
    }

    fun allWords(): List<String> = entries.keys.toList().sorted()
}
